(() => {
	// Dark mode is the default. Only switch to light if the visitor explicitly chose it.
	const stored = localStorage.getItem('darkmode'); // 'true' | 'false' | null
	const wantDark = stored === null ? true : stored === 'true';

	const applyTheme = (isDark) => {
		document.body.classList.toggle('dark-theme', isDark);
		$$('input[name=toggle-darkmode]').forEach((toggle) => {
			toggle.checked = isDark;
		});
	};
	applyTheme(wantDark);

	// Delegate the change event so the footer toggle works regardless of when it appears...
	document.addEventListener('change', (event) => {
		const target = event.target;
		if (target && target.name === 'toggle-darkmode') {
			localStorage.setItem('darkmode', target.checked);
			applyTheme(target.checked);
		}
	});

	// ...and sync the injected control's checked state once it exists.
	const syncControls = () => {
		const controls = $$('input[name=toggle-darkmode]');
		if (!controls.length) {
			return false;
		}
		const isDark = document.body.classList.contains('dark-theme');
		controls.forEach((toggle) => {
			toggle.checked = isDark;
		});
		return true;
	};
	if (!syncControls()) {
		const observer = new MutationObserver(() => {
			if (syncControls()) {
				observer.disconnect();
			}
		});
		observer.observe(document.body, { childList: true, subtree: true });
	}

	// Keep the favicon's dark variant in sync with the OS preference.
	const mediaQuery = window.matchMedia('(prefers-color-scheme:dark)');
	const syncFavicon = () => {
		$$('.js-site-favicon').forEach((link) => {
			link.href = link.href
				.replace(/-dark/, '')
				.replace(/(\.\w+)$/, (mediaQuery.matches ? '-dark' : '') + '$1');
		});
	};
	if (mediaQuery.addEventListener) {
		mediaQuery.addEventListener('change', syncFavicon);
	} else {
		mediaQuery.addListener(syncFavicon);
	}
	syncFavicon();
})();

const attachMenuToggle = () => {
	const nav = document.querySelector('nav');
	if (!nav) {
		return false;
	}

	const button = nav.querySelector('button');
	if (!button) {
		return false;
	}

	button.addEventListener('click', () => {
		nav.classList.toggle('show-menu');
	});

	// Mobile dropdown toggle - click instead of hover
	const dropdowns = nav.querySelectorAll('.dropdown-menu');
	dropdowns.forEach((dropdown) => {
		const trigger = dropdown.querySelector('span');
		if (trigger) {
			trigger.addEventListener('click', (e) => {
				e.stopPropagation();
				// Close other dropdowns
				dropdowns.forEach((d) => {
					if (d !== dropdown) d.classList.remove('open');
				});
				dropdown.classList.toggle('open');
			});
		}
	});

	return true;
};

const initMenuToggle = () => {
	if (attachMenuToggle()) {
		return;
	}

	const observer = new MutationObserver(() => {
		if (attachMenuToggle()) {
			observer.disconnect();
		}
	});

	observer.observe(document.body, { childList: true, subtree: true });
};

if (document.readyState === 'loading') {
	document.addEventListener('DOMContentLoaded', initMenuToggle);
} else {
	initMenuToggle();
}

// Click-to-load YouTube facade (keeps ~500KB of player JS out of initial load)
document.addEventListener('click', (event) => {
	const facade = event.target.closest && event.target.closest('.yt-facade');
	if (!facade) return;
	const iframe = document.createElement('iframe');
	iframe.src = 'https://www.youtube.com/embed/' + facade.dataset.ytId + '?autoplay=1';
	iframe.title = 'Airstrike demonstration video';
	iframe.allow = 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';
	iframe.allowFullscreen = true;
	iframe.style.cssText = 'width:100%;height:100%;border:0;border-radius:inherit';
	facade.replaceWith(iframe);
});
